import type { SdgnMissionQcm } from "./sdgnMissionQcmBank";

/** Banque officielle du DS SDGN Terminale (100 QCM). */
export const SDGN_DS_TERMINALE_QCM: SdgnMissionQcm[] = [
  { id: "sdgn-t-ds-01", chapter: 5, difficulte: "difficile", question: "Une start-up décide de lever des fonds en vendant de nouvelles actions à des investisseurs sur une plateforme internet.", choix: ["C'est du Crowdsourcing, car c'est un financement externe augmentant les capitaux propres.", "C'est du Crowdsourcing, car c'est un financement externe augmentant la dette.", "C'est du Crowdfunding (Equity), car c'est un financement externe augmentant les capitaux propres.", "C'est du Crowdfunding (Equity), car c'est un financement externe augmentant la dette."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-02", chapter: 5, difficulte: "difficile", question: "Le Fonds de Roulement Net Global (FRNG) de \"MecaParts\" est de 50 000€ et son Besoin en Fonds de Roulement (BFR) est de 80 000€.", choix: ["La Trésorerie Nette est positive (+30 000€), car les ressources stables couvrent le BFR.", "La Trésorerie Nette est positive (+30 000€), car le BFR couvre les ressources stables.", "La Trésorerie Nette est négative (-30 000€), car les ressources stables ne couvrent pas le BFR.", "La Trésorerie Nette est négative (-30 000€), car le BFR couvre les ressources stables."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-03", chapter: 5, difficulte: "difficile", question: "Le fabricant de pneus Michelin a cessé de vendre certains pneus aux routiers pour facturer \"le kilomètre parcouru\", incluant l'entretien.", choix: ["C'est un modèle Freemium, car il remplace la vente du bien par la vente de la performance d'usage.", "C'est un modèle Freemium, car il remplace la gratuité de base par une option payante.", "C'est l'économie de la fonctionnalité, car il remplace la vente du bien par la vente de la performance d'usage.", "C'est l'économie de la fonctionnalité, car il remplace la gratuité de base par une option payante."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-04", chapter: 5, difficulte: "difficile", question: "Les charges de loyer et d'assurance de l'usine restent identiques même si la production chute de moitié suite à une crise.", choix: ["Ce sont des charges variables, car elles sont indépendantes de l'activité.", "Ce sont des charges variables, car elles sont proportionnelles à l'activité.", "Ce sont des charges fixes, car elles sont indépendantes de l'activité.", "Ce sont des charges fixes, car elles sont proportionnelles à l'activité."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-05", chapter: 5, difficulte: "difficile", question: "L'usine \"Toyota\" ne lance la fabrication d'une voiture que lorsqu'un client a formellement signé la commande en concession.", choix: ["C'est une logistique en flux poussés, déclenchée par la demande réelle pour limiter les stocks.", "C'est une logistique en flux poussés, déclenchée par les prévisions pour saturer l'usine.", "C'est une logistique en flux tendus, déclenchée par la demande réelle pour limiter les stocks.", "C'est une logistique en flux tendus, déclenchée par les prévisions pour saturer l'usine."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-06", chapter: 5, difficulte: "difficile", question: "Pour éviter d'inscrire l'achat d'une machine (100 000€) dans ses dettes au bilan, le dirigeant opte pour un loyer avec option d'achat.", choix: ["Il utilise l'autofinancement, un financement interne hors bilan.", "Il utilise l'autofinancement, un financement externe préservant la capacité d'endettement.", "Il utilise le crédit-bail, un financement interne hors bilan.", "Il utilise le crédit-bail, un financement externe préservant la capacité d'endettement bilanciel."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-07", chapter: 5, difficulte: "difficile", question: "Un artisan calcule que la vente de chaque meuble couvre ses coûts d'achat et dégage un surplus de 200€.", choix: ["Il a calculé sa valeur ajoutée, qui permet d'absorber les charges fixes.", "Il a calculé sa valeur ajoutée, qui mesure l'EBE (Excédent Brut d'Exploitation).", "Il a calculé sa marge sur coût variable (MCV), qui permet d'absorber les charges fixes.", "Il a calculé sa marge sur coût variable (MCV), qui mesure l'EBE (Excédent Brut d'Exploitation)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-08", chapter: 5, difficulte: "difficile", question: "L'entreprise vend l'imprimante à perte, mais se rattrape en vendant les cartouches d'encre indispensables très cher.", choix: ["C'est un modèle Freemium, car la rentabilité repose sur les consommables captifs.", "C'est un modèle Freemium, car l'offre de base est gratuite.", "C'est un modèle \"Bait and Hook\" (appât et hameçon), car la rentabilité repose sur les consommables captifs.", "C'est un modèle \"Bait and Hook\" (appât et hameçon), car l'offre de base est gratuite."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-09", chapter: 5, difficulte: "difficile", question: "En analyse fonctionnelle, le décalage financier entre les paiements aux fournisseurs et les encaissements des clients génère :", choix: ["Le Fonds de Roulement Net Global (FRNG), lié au cycle d'investissement.", "Le Fonds de Roulement Net Global (FRNG), lié au cycle d'exploitation.", "Le Besoin en Fonds de Roulement (BFR), lié au cycle d'investissement.", "Le Besoin en Fonds de Roulement (BFR), lié au cycle d'exploitation."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-10", chapter: 5, difficulte: "difficile", question: "La comptabilité intègre chaque année la perte de valeur liée à l'usure des camions de livraison dans ses charges.", choix: ["C'est l'amortissement comptable, considéré comme une charge variable de structure.", "C'est l'amortissement comptable, considéré comme une charge fixe de structure.", "C'est la provision financière, considérée comme une charge variable de structure.", "C'est la provision financière, considérée comme une charge fixe de structure."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-11", chapter: 5, difficulte: "difficile", question: "Zara renouvelle ses collections en permanence et produit de petites séries selon les ventes réelles constatées en magasin.", choix: ["Sa Supply Chain vise l'efficience par la saturation des usines (flux poussés).", "Sa Supply Chain vise l'agilité et la réactivité à la demande (flux tendus).", "Sa Supply Chain vise l'efficience par le stockage massif (flux tendus).", "Sa Supply Chain vise l'agilité par la saturation des usines (flux poussés)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-12", chapter: 5, difficulte: "difficile", question: "Une PME a une trésorerie nette (TN) structurellement négative. L'analyse révèle que :", choix: ["Ses ressources stables (FRNG) sont supérieures à son cycle d'exploitation (BFR).", "Ses ressources stables (FRNG) sont insuffisantes pour financer son cycle d'exploitation (BFR).", "Ses clients la paient plus rapidement que ses fournisseurs.", "Ses investissements ont été entièrement autofinancés."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-13", chapter: 5, difficulte: "difficile", question: "L'usine fabrique le produit B dont la marge sur coût spécifique est négative de 10 000€.", choix: ["Il faut conserver le produit B, car il couvre la marge sur coût variable.", "Il faut conserver le produit B, car il absorbe les charges fixes communes indirectes.", "Il faut abandonner le produit B, car il ne parvient même pas à couvrir ses propres charges fixes directes.", "Il faut abandonner le produit B, car il détruit la valeur partenariale."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-14", chapter: 5, difficulte: "difficile", question: "L'État verse une subvention pour le maintien à domicile des personnes âgées dépendantes.", choix: ["Cette organisation publique produit un service marchand, financé par les impôts et subventions.", "Cette organisation publique produit un service marchand, dont l'efficacité se mesure par la rentabilité financière.", "Cette organisation publique produit un service non marchand, financé par les impôts et subventions.", "Cette organisation publique produit un service non marchand, dont l'efficacité se mesure par la rentabilité financière."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-15", chapter: 5, difficulte: "difficile", question: "Une usine de skateboards subit une chute des commandes de 30% mais conserve toutes ses machines et locaux.", choix: ["Le coût variable unitaire va augmenter, réduisant la rentabilité (effet de ciseau).", "Le coût variable unitaire va diminuer, réduisant la rentabilité (effet de ciseau).", "Le coût fixe unitaire va augmenter, réduisant la rentabilité car les charges se répartissent sur moins de produits.", "Le coût fixe unitaire va diminuer, réduisant la rentabilité car les charges se répartissent sur moins de produits."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-16", chapter: 5, difficulte: "difficile", question: "Une ONG environnementale dépend exclusivement des dons citoyens.", choix: ["Sa performance financière se mesure par le maintien d'un équilibre budgétaire (dépenses couvertes par les dons).", "Sa performance financière se mesure par la rentabilité de ses capitaux propres.", "Sa performance commerciale se mesure par le maintien d'un équilibre budgétaire (dépenses couvertes par les dons).", "Sa performance commerciale se mesure par la rentabilité de ses capitaux propres."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-17", chapter: 5, difficulte: "difficile", question: "Dans la méthode des coûts complets, le loyer du siège social et le salaire du PDG sont considérés comme :", choix: ["Des charges variables directes, imputées aux produits selon des unités d'œuvre.", "Des charges variables directes, affectées directement aux produits.", "Des charges fixes indirectes, imputées aux produits selon des unités d'œuvre (clés de répartition).", "Des charges fixes indirectes, affectées directement aux produits."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-18", chapter: 5, difficulte: "difficile", question: "Une start-up lève 2 millions d'euros sur une plateforme internet en échange d'une prise de participation (Equity).", choix: ["C'est du Crowdfunding, un mode de financement externe qui augmente la dette.", "C'est du Crowdfunding, un mode de financement externe qui augmente les capitaux propres.", "C'est du Shadow IT, un mode de financement externe qui augmente la dette.", "C'est du Shadow IT, un mode de financement externe qui augmente les capitaux propres."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-19", chapter: 5, difficulte: "difficile", question: "L'Excédent Brut d'Exploitation (EBE) est un solde intermédiaire de gestion crucial car :", choix: ["Il mesure la rentabilité du seul cycle d'exploitation (coeur de métier) avant amortissements et intérêts.", "Il mesure le résultat net final (après impôts, amortissements et intérêts) distribuable aux actionnaires.", "Il indique la trésorerie exacte disponible en banque au 31 décembre.", "Il indique la capacité de l'entreprise à lever de la dette obligataire à court terme."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-20", chapter: 5, difficulte: "difficile", question: "Lors de l'Affectation du Résultat, l'entreprise décide de conserver une partie du bénéfice net (mise en réserves).", choix: ["C'est le dividende, qui permet de rémunérer les actionnaires.", "C'est le dividende, qui permet de financer les investissements futurs.", "C'est l'autofinancement, qui permet de rémunérer les actionnaires.", "C'est l'autofinancement, qui permet de financer les investissements futurs (pérennité)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-21", chapter: 5, difficulte: "difficile", question: "Une entreprise affiche un CA de 800 000€, des achats de marchandises de 300 000€, et paie 200 000€ de salaires.", choix: ["Sa Valeur Ajoutée (VA) est de 300 000€ (CA - achats - salaires).", "Sa Valeur Ajoutée (VA) est de 500 000€ (CA - achats).", "Son Résultat Net est de 500 000€ (CA - achats).", "Son Résultat Net est de 300 000€ (CA - achats - salaires)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-22", chapter: 5, difficulte: "difficile", question: "La capacité d'une entreprise à honorer ses dettes à court terme sans risquer la cessation de paiements s'évalue par :", choix: ["L'analyse de sa liquidité (Trésorerie et BFR).", "L'analyse de sa rentabilité financière (ROE).", "L'analyse de sa profitabilité (Marge nette).", "L'analyse de son autofinancement."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-23", chapter: 5, difficulte: "difficile", question: "L'entreprise \"FourniBat\" allonge le délai de règlement accordé à ses clients de 30 à 60 jours.", choix: ["Mathématiquement, son FRNG va augmenter, améliorant sa trésorerie nette.", "Mathématiquement, son FRNG va diminuer, dégradant sa trésorerie nette.", "Mathématiquement, son BFR va augmenter, dégradant sa trésorerie nette.", "Mathématiquement, son BFR va diminuer, améliorant sa trésorerie nette."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-24", chapter: 5, difficulte: "difficile", question: "Les compagnies aériennes modifient dynamiquement le prix des billets en fonction de la demande (heure, taux de remplissage).", choix: ["C'est du Yield Management, visant à fixer un prix d'écrémage unique.", "C'est du Yield Management, visant à maximiser le CA d'une capacité fixe (avion).", "C'est de la domination par les coûts, visant à fixer un prix d'écrémage unique.", "C'est de la domination par les coûts, visant à maximiser le CA d'une capacité fixe (avion)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-25", chapter: 5, difficulte: "difficile", question: "Dans la chaîne de valeur de M. Porter, la \"logistique interne\", la \"production\" et la \"commercialisation\" constituent :", choix: ["Les activités de soutien, générant indirectement de la valeur pour le client final.", "Les activités de soutien, créant directement l'offre pour le client final.", "Les activités principales, générant indirectement de la valeur pour le client final.", "Les activités principales, créant directement la valeur de l'offre pour le client final."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-26", chapter: 5, difficulte: "difficile", question: "L'acquisition d'un Progiciel de Gestion Intégré (PGI/ERP) très coûteux est comptabilisée au bilan comme :", choix: ["Une immobilisation corporelle (investissement amortissable à long terme).", "Une immobilisation incorporelle (investissement immatériel amortissable à long terme).", "Une charge d'exploitation exceptionnelle détruisant le résultat de l'année.", "Un décaissement neutre pour le compte de résultat."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-27", chapter: 5, difficulte: "difficile", question: "La désintermédiation permet à un producteur de vendre directement sur son site web sans passer par les magasins distributeurs.", choix: ["Le but est de capter la marge commerciale des distributeurs pour accroître sa propre profitabilité.", "Le but est d'augmenter les charges fixes liées au commissionnement des intermédiaires.", "Le but est d'allonger le délai de paiement du BFR fournisseur.", "Le but est de réduire la valeur ajoutée globale du produit."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-28", chapter: 5, difficulte: "difficile", question: "En période de forte inflation des matières premières, si l'entreprise ne peut pas augmenter son prix de vente (pression concurrentielle), elle subit :", choix: ["Un effet de levier financier positif sur sa rentabilité.", "Un effet de levier financier négatif sur sa rentabilité.", "Un effet de ciseau, la hausse des charges écrasant mathématiquement sa marge bénéficiaire.", "Un effet de ciseau, la hausse des charges dopant artificiellement son seuil de rentabilité."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-29", chapter: 5, difficulte: "difficile", question: "Le ratio (Bénéfice Net / Chiffre d'Affaires) permet d'évaluer la :", choix: ["Rentabilité financière de l'organisation.", "Profitabilité (marge nette) de l'organisation.", "Valeur partenariale de l'organisation.", "Capacité d'autofinancement de l'organisation."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-30", chapter: 5, difficulte: "difficile", question: "Le ratio (Bénéfice Net / Capitaux Propres) permet d'évaluer la :", choix: ["Rentabilité financière de l'organisation.", "Profitabilité (marge nette) de l'organisation.", "Valeur partenariale de l'organisation.", "Capacité d'autofinancement de l'organisation."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-31", chapter: 5, difficulte: "difficile", question: "Si le FRNG est de 200 000€ et l'Actif Immobilisé (Emplois stables) de 500 000€, à combien s'élèvent les Ressources Stables (capitaux propres et emprunts longs) ?", choix: ["300 000€ (Actif Immobilisé - FRNG).", "300 000€ (FRNG + Actif Immobilisé).", "700 000€ (Actif Immobilisé - FRNG).", "700 000€ (FRNG + Actif Immobilisé)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-32", chapter: 5, difficulte: "difficile", question: "Une entreprise lance un nouveau smartphone technologique à un prix délibérément très supérieur au coût de production.", choix: ["C'est une stratégie de pénétration, visant à maximiser le volume des ventes rapides.", "C'est une stratégie de pénétration, ciblant les \"innovateurs\" prêts à payer pour la nouveauté.", "C'est une stratégie d'écrémage, visant à maximiser le volume des ventes rapides.", "C'est une stratégie d'écrémage, ciblant les \"innovateurs\" pour maximiser la marge unitaire."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-33", chapter: 5, difficulte: "difficile", question: "Une entreprise B2B constate que le délai de rotation (encaissement) de ses créances clients est passé de 30 jours à 90 jours (moyenne du secteur : 40 jours).", choix: ["C'est le signe d'un FRNG excédentaire face aux dettes fournisseurs.", "C'est le signe d'une excellente politique de prix d'écrémage.", "C'est le signe d'un lourd Besoin en Fonds de Roulement (BFR) pesant dangereusement sur la trésorerie et le risque d'impayés.", "C'est le signe d'une domination par les coûts réussie face à la concurrence."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-34", chapter: 5, difficulte: "difficile", question: "Le plan de financement prévisionnel est un outil essentiel car il sert à :", choix: ["Analyser rétrospectivement la rentabilité financière de l'année N-1.", "Anticiper si les ressources futures (autofinancement, emprunts) couvriront les emplois futurs (investissements prévus).", "Calculer le coût marginal du dernier produit fabriqué.", "Déclarer officiellement l'impôt sur les sociétés."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-35", chapter: 5, difficulte: "difficile", question: "L'introduction en Bourse (IPO) d'une grande entreprise permet de lever des fonds de financement de manière :", choix: ["Interne, par l'augmentation de l'endettement bancaire (dettes).", "Interne, par l'augmentation du capital ouvert au public (capitaux propres).", "Externe, par l'augmentation de l'endettement bancaire (dettes).", "Externe, par l'augmentation du capital ouvert au public (capitaux propres)."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-36", chapter: 5, difficulte: "difficile", question: "Le PDG prend toutes les décisions seul, ne consulte personne et utilise la menace de licenciement pour maintenir les quotas de production.", choix: ["Son style (Likert) est consultatif, car il s'appuie sur la crainte et la contrainte.", "Son style (Likert) est consultatif, car il centralise le pouvoir par la récompense.", "Son style (Likert) est autoritaire exploiteur, car il s'appuie sur la crainte et la contrainte.", "Son style (Likert) est autoritaire exploiteur, car il centralise le pouvoir par la récompense."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-37", chapter: 5, difficulte: "difficile", question: "Un groupe d'infirmiers refuse de porter une nouvelle blouse qu'ils jugent dégradante pour la dignité de leur profession. Ce conflit est un conflit :", choix: ["D'intérêts, car il porte sur les conditions matérielles du contrat de travail.", "D'intérêts, car il porte sur l'éthique et l'identité du métier.", "De valeurs, car il porte sur les conditions matérielles du contrat de travail.", "De valeurs, car il porte sur l'éthique et l'identité du métier."] as [string, string, string, string], bonIndex: 3 },
  { id: "sdgn-t-ds-38", chapter: 5, difficulte: "difficile", question: "La direction d'un grand magasin décide d'isoler un salarié syndicaliste dans un bureau lointain et de l'ignorer en espérant qu'il démissionne.", choix: ["Le mode de résolution du conflit est le dépassement.", "Le mode de résolution du conflit est l'ajustement mutuel.", "Le mode de résolution du conflit est l'évitement.", "Le mode de résolution du conflit est le recours hiérarchique."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-39", chapter: 5, difficulte: "difficile", question: "Selon F.W. Taylor (l'OST), l'augmentation de la performance industrielle s'obtient prioritairement par :", choix: ["L'enrichissement des tâches et le développement de l'autonomie ouvrière.", "La séparation stricte entre la conception intellectuelle et l'exécution, et la parcellisation (division) extrême des tâches chronométrées.", "La GPEC et le déploiement de l'intelligence collective asynchrone.", "L'application systématique d'un style de direction participatif."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-40", chapter: 2, difficulte: "difficile", question: "Pour Frederick Herzberg, si l'on augmente le salaire d'un cadre qui s'ennuie intellectuellement dans ses fonctions :", choix: ["Cela éliminera son insatisfaction immédiate (facteur d'hygiène), mais cela ne créera aucune véritable motivation durable (réservée aux facteurs moteurs).", "Cela éliminera son insatisfaction immédiate (facteur moteur), mais cela ne créera aucune véritable motivation durable (réservée aux facteurs d'hygiène).", "Cela le motivera durablement (facteur d'hygiène), l'argent étant le seul levier d'accomplissement.", "Cela le motivera durablement (facteur moteur), l'argent étant le seul levier d'accomplissement."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-41", chapter: 2, difficulte: "difficile", question: "Le taux de \"Turn-over\" (rotation du personnel) d'un service client monte en flèche à 35%. L'analyse RH en déduit :", choix: ["Un indicateur de performance commerciale en très forte hausse.", "L'instauration d'un excellent climat social favorisant la flexibilité externe.", "Un dysfonctionnement social profond (mauvaises conditions de travail) générant de lourds coûts cachés (frais de recrutement, perte de qualité).", "La réussite indiscutable de la stratégie de marque employeur de l'entreprise."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-42", chapter: 2, difficulte: "difficile", question: "La \"Marque Employeur\" (Marketing RH) est utilisée par la direction de l'entreprise pour :", choix: ["Augmenter le prix de vente des produits auprès des clients (B2C) et rassurer les investisseurs (asymétrie d'information).", "Rendre l'entreprise attractive aux yeux des candidats externes et fidéliser les salariés actuels dans un contexte de guerre des talents.", "Publier légalement le bilan comptable et fonctionnel annuel sur les réseaux sociaux.", "Négocier avec les banques commerciales des taux d'intérêt plus favorables au financement du BFR."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-43", chapter: 2, difficulte: "difficile", question: "Lors de l'Assemblée Générale d'une SCOP (Société Coopérative), le principe \"1 personne = 1 voix\" s'applique lors du vote.", choix: ["Cela illustre la centralisation du pouvoir décisionnel entre les mains des actionnaires majoritaires fondateurs.", "Cela illustre une gouvernance démocratique participative où le pouvoir de décision est dissocié de l'apport financier (capital) du votant.", "Cela illustre un mécanisme d'ajustement mutuel contraint par la loi sur les sociétés commerciales.", "Cela illustre l'application stricte des algorithmes d'Open Data décisionnel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-44", chapter: 2, difficulte: "difficile", question: "L'élargissement des tâches, tel qu'il est défini en GRH, consiste à :", choix: ["Accorder au salarié des tâches incluant conception et contrôle qualité (hausse de l'autonomie et de la responsabilité intellectuelle).", "Augmenter le salaire de l'employé proportionnellement au temps de travail effectif (heures supplémentaires).", "Confier au salarié un plus grand nombre de tâches d'exécution de même niveau de complexité (polyvalence horizontale).", "Externaliser purement et simplement le travail d'exécution vers un sous-traitant (flexibilité)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-45", chapter: 2, difficulte: "difficile", question: "L'enrichissement des tâches, tel qu'il est défini en GRH, consiste à :", choix: ["Accorder au salarié des tâches incluant conception et contrôle qualité (hausse de l'autonomie et de la responsabilité intellectuelle verticale).", "Augmenter le salaire de l'employé proportionnellement au temps de travail effectif (heures supplémentaires).", "Confier au salarié un plus grand nombre de tâches d'exécution de même niveau de complexité (polyvalence horizontale).", "Externaliser purement et simplement le travail d'exécution vers un sous-traitant (flexibilité)."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-46", chapter: 2, difficulte: "difficile", question: "Un chirurgien renommé de l'hôpital impose le protocole opératoire à un infirmier avec lequel il n'a aucun lien de subordination juridique.", choix: ["Son influence sur le groupe repose sur son autorité formelle légale.", "Son influence sur le groupe repose sur l'influence affective (empathie).", "Son influence sur le groupe repose sur son expertise, son savoir-faire et sa compétence (leadership technique reconnu).", "Son influence sur le groupe repose sur la coercition et les sanctions salariales."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-47", chapter: 2, difficulte: "difficile", question: "L'entreprise cartographie les départs massifs en retraite prévus d'ici 5 ans pour anticiper les embauches et les formations nécessaires au remplacement des savoir-faire stratégiques.", choix: ["C'est la démarche du Bilan Social obligatoire.", "C'est la démarche de la RSE environnementale.", "C'est la démarche de la GPEC (Gestion Prévisionnelle des Emplois et des Compétences).", "C'est la démarche du Yield Management des salaires variables."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-48", chapter: 2, difficulte: "difficile", question: "En pleine Assemblée, les associés exigent 80% des profits en dividendes, tandis que les salariés réclament que cette somme finance une augmentation générale de 5%. C'est :", choix: ["Un conflit de valeurs éthiques sur la RSE.", "Un conflit d'intérêts fondamental portant sur la répartition financière de la richesse créée (Valeur Ajoutée).", "Une divergence culturelle de l'organisation due à un manque de rituels.", "Un problème de standardisation des procédés selon Mintzberg."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-49", chapter: 2, difficulte: "difficile", question: "La participation et l'intéressement (primes) sont des dispositifs légaux mis en place visant à :", choix: ["Remplacer illégalement le versement du salaire minimum (SMIC).", "Associer financièrement les salariés aux résultats ou aux performances de l'entreprise pour aligner leurs intérêts et accroître leur motivation.", "Rémunérer les fournisseurs de matières premières avec des actions de l'entreprise.", "Financer le Besoin en Fonds de Roulement (BFR) en sollicitant l'épargne des clients."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-50", chapter: 2, difficulte: "difficile", question: "Une PME a une structure simple : le patron (fondateur) décide de la stratégie et contrôle tous ses ouvriers directement dans l'atelier sans aucun cadre intermédiaire.", choix: ["Le mécanisme de coordination de Mintzberg est la standardisation des résultats.", "Le mécanisme de coordination de Mintzberg est la supervision directe (le chef donne les ordres et contrôle l'exécution).", "Le mécanisme de coordination de Mintzberg est l'ajustement mutuel informel.", "Le mécanisme de coordination de Mintzberg est la standardisation des qualifications."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-51", chapter: 2, difficulte: "difficile", question: "Deux développeurs informatiques se coordonnent de manière totalement informelle, discutant toute la journée pour coder une application complexe inédite sans procédure préétablie.", choix: ["Le mécanisme de coordination de Mintzberg est la standardisation des résultats.", "Le mécanisme de coordination de Mintzberg est la supervision directe.", "Le mécanisme de coordination de Mintzberg est l'ajustement mutuel (communication informelle face à la complexité et l'imprévu).", "Le mécanisme de coordination de Mintzberg est la standardisation des qualifications."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-52", chapter: 2, difficulte: "difficile", question: "Dans un cabinet d'avocats, les associés travaillent de manière autonome sur leurs dossiers respectifs sans se consulter, car ils ont tous obtenu le même diplôme d'État (le barreau).", choix: ["Le mécanisme de coordination est assuré en amont par la standardisation des procédés.", "Le mécanisme de coordination est assuré en amont par la standardisation des qualifications (la formation initiale dicte les méthodes de travail et les réflexes professionnels).", "Le mécanisme de coordination est assuré par la supervision directe du DRH.", "Le mécanisme de coordination est assuré par le \"Shadow IT\" juridique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-53", chapter: 2, difficulte: "difficile", question: "L'entreprise industrielle verse une \"Prime de nuit\" de 200€ aux préparateurs de commandes travaillant en horaires décalés. Ce versement représente :", choix: ["Une rémunération fixe de base indissociable de la qualification du diplôme.", "Une incitation (rémunération variable/périphérique) liée aux conditions ou aux résultats de l'activité.", "Le versement d'un dividende social participatif.", "Une charge fixe d'exploitation indépendante du volume de travail."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-54", chapter: 2, difficulte: "difficile", question: "La théorie de la \"Contingence\" (Joan Woodward, Lawrence & Lorsch) stipule en management des organisations que :", choix: ["Il existe une structure organisationnelle parfaite et universelle applicable à toutes les entreprises (\"One best way\").", "La \"meilleure\" structure dépend toujours des facteurs de contingence externes et internes (âge, taille, technologie, stabilité de l'environnement) propres à l'entreprise.", "Le salaire est l'unique facteur de contingence expliquant la motivation ou la démotivation des ouvriers.", "La hiérarchie décisionnelle doit rester invariablement centralisée, quelle que soit la taille de la structure."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-55", chapter: 2, difficulte: "difficile", question: "Dans une organisation \"matricielle\" (structure croisée), la principale difficulté pour un salarié réside dans le fait qu'il :", choix: ["Ne possède statutairement plus aucun supérieur hiérarchique direct.", "Dépend simultanément d'une double ligne hiérarchique (ex: un chef de département métier ET un chef de produit transverse), risquant de générer des conflits d'autorité.", "Doit gérer exclusivement les relations fournisseurs en flux tendus (JAT).", "N'est rémunéré qu'au travers des dividendes distribués en fin d'exercice comptable."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-56", chapter: 2, difficulte: "difficile", question: "L'externalisation (Outsourcing) de la hotline du service client vers un prestataire basé en Asie présente pour l'entreprise le risque majeur de :", choix: ["Transformer ses charges variables d'exploitation en lourdes charges fixes (effet de levier négatif).", "Perdre le contrôle sur la qualité de l'expérience client (CX) et subir une forte dépendance stratégique vis-à-vis du prestataire étranger.", "Augmenter la valeur partenariale de manière excessive avec ses propres salariés français.", "Se voir interdire l'usage du Cloud Computing et du RGPD par l'État français."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-57", chapter: 2, difficulte: "difficile", question: "Le \"Droit à la déconnexion\" a été instauré légalement par le code du travail pour lutter principalement contre :", choix: ["Les cyberattaques et fuites de données de type DDoS sur les serveurs de l'entreprise (Shadow IT).", "L'effondrement constaté de la productivité industrielle (chute du ROI) lors des phases de télétravail.", "La porosité toxique entre la vie professionnelle et la vie personnelle induite par l'hyper-connexion aux outils numériques (smartphones, mails), génératrice de Risques Psychosociaux (burn-out, stress).", "L'utilisation abusive de l'Open Data gouvernemental par les collaborateurs de la DSI."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-58", chapter: 2, difficulte: "difficile", question: "L'adoption d'une structure \"Divisionnelle\" (décentralisée par divisions autonomes) est stratégiquement indispensable pour une entreprise qui :", choix: ["Ne vend qu'un seul produit sur un marché local unique très ciblé.", "Est fortement diversifiée (opérant sur plusieurs métiers très différents ou sur de nombreux continents isolés) et qui nécessite que chaque pôle réagisse rapidement à son propre marché.", "Souhaite recentraliser 100% du pouvoir décisionnel opérationnel au siège social parisien.", "Souhaite fonctionner exclusivement par ajustement mutuel informel, sans aucune hiérarchie intermédiaire."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-59", chapter: 2, difficulte: "difficile", question: "Le Bilan Social (obligatoire dans les entreprises de plus de 300 salariés) synthétise obligatoirement des indicateurs qualitatifs et quantitatifs comme :", choix: ["L'EBE, le FRNG et l'évolution du BFR sur les 3 dernières années d'exploitation.", "Les effectifs, l'absentéisme, les accidents du travail, les rémunérations et les frais de formation sur les 3 dernières années.", "L'empreinte carbone, la pollution de l'air et les rejets toxiques de l'usine sur les 3 dernières années (Bilan Carbone).", "Le cours boursier de l'action, les OPA et la valorisation financière sur les 3 dernières années."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-60", chapter: 2, difficulte: "difficile", question: "Une culture d'entreprise forte, partagée à travers des rites, des mythes et des valeurs solides, a pour effet managérial de :", choix: ["Détruire la marque employeur auprès de la nouvelle génération Z (digital natives).", "Fédérer les collaborateurs, faciliter leur intégration rapide et fournir un cadre décisionnel commun qui limite le besoin de contrôles formels et de procédures bureaucratiques strictes.", "Obliger l'entreprise à adopter légalement le statut de Société Coopérative et Participative (SCOP).", "Rendre la Gestion Prévisionnelle des Emplois et des Compétences (GPEC) totalement obsolète et inutile."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-61", chapter: 2, difficulte: "difficile", question: "Face à un taux de rebut (défauts de fabrication) très élevé, la direction instaure les principes du \"Lean Management\", ce qui implique concrètement :", choix: ["D'embaucher massivement des contrôleurs qualité (supervision directe) situés exclusivement en toute fin de chaîne de montage.", "D'impliquer tous les opérateurs de base dans la chasse méthodique aux gaspillages (temps, matière) et dans l'amélioration continue (Kaizen) de la qualité, directement au niveau de leur poste de travail.", "D'augmenter les stocks de sécurité (matières premières) pour cacher les défauts dans la chaîne logistique (Supply Chain).", "De recentraliser toutes les décisions techniques relatives à la qualité à la direction générale basée à Paris."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-62", chapter: 2, difficulte: "difficile", question: "En sociologie des organisations, le \"Contrat psychologique\" liant l'employé et son employeur désigne :", choix: ["Le contrat de travail écrit à durée indéterminée (CDI) validé par l'avocat d'affaires de l'entreprise.", "L'ensemble des attentes et obligations implicites réciproques (non formalisées par écrit) : par exemple, la loyauté et l'implication de l'employé en échange d'employabilité et d'évolution de carrière garanties par l'employeur.", "L'accord formel d'intéressement aux bénéfices validé et signé par le Comité Social et Économique (CSE).", "Le document légal d'habilitation relatif à la charte informatique et au traitement des données personnelles (RGPD) de l'entreprise."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-63", chapter: 2, difficulte: "difficile", question: "L'intelligence collective au sein d'une équipe gérant un projet d'innovation complexe s'épanouit de manière optimale si la structure de l'organisation est :", choix: ["Cloisonnée en silos métiers hermétiques (structure fonctionnelle rigide et pyramidale).", "Transversale et décloisonnée (structure par projet / matricielle), favorisant l'échange d'informations horizontal entre des profils complémentaires.", "Totalement centralisée et hyper-bureaucratique (standardisation extrême des procédés).", "Exclusivement basée sur une rémunération variable individuelle ultra-compétitive encourageant la compétition interne."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-64", chapter: 2, difficulte: "difficile", question: "Un lanceur d'alerte, salarié d'un laboratoire, alerte publiquement que l'entreprise déverse secrètement des produits toxiques dans la rivière voisine au lieu de les recycler.", choix: ["Il est légalement licenciable pour faute lourde, caractérisée par la divulgation du secret des affaires et l'atteinte à l'image de marque.", "Il est protégé par la loi contre les sanctions hiérarchiques, à la condition expresse qu'il agisse de bonne foi et de manière désintéressée dans l'intérêt général face à un danger grave.", "Il n'est protégé par la loi que s'il réclame officiellement une récompense financière à la justice pénale (commission).", "Il est tenu, selon le principe de la blockchain, de publier anonymement l'intégralité des données confidentielles sur le Dark Web."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-65", chapter: 2, difficulte: "difficile", question: "Le recrutement via l'utilisation de \"CV anonymes\" (sans nom, âge, ou photo) ou de grilles d'évaluation techniques standardisées vise stratégiquement la DRH à :", choix: ["Baisser les coûts spécifiques et les charges variables associés aux cabinets de recrutement.", "Garantir l'équité, contourner les biais cognitifs inconscients (stéréotypes, préjugés discriminatoires) des recruteurs et se focaliser sur les compétences réelles (hard skills).", "Éviter l'application des lourdes sanctions du RGPD en ne stockant aucune donnée personnelle pendant 5 ans.", "Réduire l'employabilité et bloquer l'évolution de carrière des cadres seniors (plus de 55 ans) de l'entreprise."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-66", chapter: 2, difficulte: "difficile", question: "La théorie de l'Agence (concept de M. Jensen & W. Meckling) met en évidence le conflit d'intérêts financier et stratégique fondamental pouvant survenir entre :", choix: ["L'État (qui souhaite maximiser l'impôt perçu) et les banquiers prêteurs (qui souhaitent la stabilité).", "Le dirigeant (l'Agent) qui peut être tenté de viser la croissance, le prestige ou sa propre rémunération, et l'actionnaire (le Principal) qui exige la maximisation de la rentabilité financière et des dividendes.", "Les syndicats de salariés (qui veulent des salaires) et le médecin du travail (qui souhaite limiter la productivité).", "Le DSI (qui veut bloquer le Cloud) et le service marketing (qui veut déployer le Big Data)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-67", chapter: 2, difficulte: "difficile", question: "La flexibilité \"quantitative externe\", très prisée dans certains secteurs (BTP, grande distribution), consiste pour la direction RH à :", choix: ["Demander aux salariés embauchés en CDI de réaliser massivement des heures supplémentaires non rémunérées.", "Poly-former (qualifier) les ouvriers pour qu'ils puissent changer de poste d'une heure à l'autre selon les besoins de la chaîne.", "Recourir massivement à l'intérim, aux CDD courts ou à la sous-traitance pour ajuster très rapidement le volume de main-d'œuvre à la fluctuation de la demande des clients.", "Modifier en temps réel les horaires d'ouverture et de fermeture du point de vente physique (annualisation du temps de travail)."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-68", chapter: 2, difficulte: "difficile", question: "L'évolution démographique de la pyramide des âges d'une grande entreprise industrielle laisse présager un vieillissement massif de ses effectifs avec 40% de départs en retraite prévus sur 3 ans. Cela nécessite d'activer en urgence :", choix: ["Le mécanisme d'Open Data pour partager la base de données salariés avec Pôle Emploi.", "Une politique ambitieuse de GPEC (gestion du transfert de compétences rares, embauches anticipées de jeunes, tutorat).", "Le Yield Management de la grille des salaires variables pour limiter la masse salariale fixe.", "L'effet de massue financier pour payer les lourdes indemnités de départ."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-69", chapter: 2, difficulte: "difficile", question: "La promotion de la Qualité de Vie au Travail (QVT) est aujourd'hui considérée par le management comme un puissant levier de performance globale car :", choix: ["Elle augmente mathématiquement les charges fixes, ce qui améliore indirectement la valeur des immobilisations au bilan.", "Un salarié épanoui (reconnaissance, équilibre) est plus engagé, plus productif, moins absent et plus fidèle, ce qui réduit significativement les \"coûts cachés\" (RPS, turnover) destructeurs de valeur économique.", "Elle permet légalement à l'entreprise de s'affranchir du paiement de la taxe sur la valeur ajoutée (TVA) et des cotisations patronales.", "Elle impose la supervision directe du télétravail par webcam, maximisant ainsi l'efficacité des heures de travail à domicile."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-70", chapter: 3, difficulte: "difficile", question: "Le leadership \"transformationnel\" se caractérise en psychologie des organisations par un manager / leader qui :", choix: ["Gère ses équipes exclusivement par la sanction, le contrôle tatillon des procédures et le micro-management autoritaire.", "Inspire, stimule intellectuellement ses troupes, écoute leurs besoins (empathie) et donne une vision fédératrice porteuse de sens, les poussant à transcender leurs intérêts individuels pour le projet collectif.", "Fuit la responsabilité et ne prend volontairement aucune décision, laissant l'équipe s'auto-gérer dans le chaos (laisser-faire absolu).", "Utilise exclusivement l'influence paradoxale et la manipulation des informations financières asymétriques."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-71", chapter: 3, difficulte: "difficile", question: "Une start-up utilise des \"Smart Contracts\" auto-exécutables garantissant le versement d'une prime sans aucun notaire ni banque intermédiaire.", choix: ["C'est la technologie du Cloud hybride, basé sur la centralisation d'un serveur étatique.", "C'est la technologie de la Blockchain, registre numérique distribué et infalsifiable validé par consensus algorithmique.", "C'est la technologie du Big Data, analysant les comportements des assureurs.", "C'est la technologie du Shadow IT, permettant de contourner la loi de finance."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-72", chapter: 3, difficulte: "difficile", question: "Un système \"boîte noire\" (Intelligence Artificielle) suspend automatiquement les allocations d'une famille. Selon la loi imposant la \"transparence algorithmique\" :", choix: ["Le code source informatique du logiciel doit être publié en open source sur Wikipédia.", "L'administration doit pouvoir expliquer en langage clair à l'allocataire les critères, données et pondérations ayant conduit l'IA à prendre cette décision le concernant.", "Les données médicales et financières des allocataires doivent être anonymisées puis revendues en Open Data.", "Les algorithmes de décision publique doivent obligatoirement être hébergés sur des serveurs Cloud hors de l'Union Européenne."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-73", chapter: 3, difficulte: "difficile", question: "L'entreprise \"Pure Cosmetic\" affiche des feuilles vertes sur ses emballages et parle de nature, mais la composition révèle 90% d'ingrédients pétrochimiques toxiques.", choix: ["C'est une démarche de Mécénat éthique justifiée par le volume de production.", "C'est du Social washing, une démarche de RSE visant à préserver l'emploi local au détriment de l'écologie.", "C'est du Greenwashing (éco-blanchiment), une pratique de communication trompeuse créant un décalage entre le discours et la réalité, exposant la marque à un bad buzz réputationnel.", "C'est l'application optimale du Yield Management écologique, fixant les prix selon la demande verte."] as [string, string, string, string], bonIndex: 2 },
  { id: "sdgn-t-ds-74", chapter: 3, difficulte: "difficile", question: "La marque de vêtements d'extérieur \"Patagonia\" garantit ses produits à vie, propose de les réparer gratuitement en atelier et reverse 1% de son chiffre d'affaires à des ONG environnementales.", choix: ["Son modèle d'affaires intègre l'obsolescence programmée esthétique stricte.", "Son modèle d'affaires intègre la RSE et l'économie circulaire au cœur de sa création de valeur (Product Lifecycle Management - allongement de la durée de vie du bien).", "Son modèle d'affaires intègre le concept économique du Low-Cost extrême.", "Son modèle d'affaires relève de l'Open Data industriel et de la désintermédiation."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-75", chapter: 3, difficulte: "difficile", question: "La plateforme \"Vinted\" ne possède pas un seul vêtement, elle se rémunère en prélevant une \"commission de protection\" sur chaque vente entre particuliers.", choix: ["Son modèle économique (Business Model) est basé sur l'intégration verticale totale des usines de production jusqu'au client final.", "Son modèle économique est basé sur l'intermédiation numérique de plateforme (C2C), bouleversant la chaîne de valeur traditionnelle grâce à la puissance des \"externalités de réseau\" (effet boule de neige).", "Son modèle économique est basé sur la stratégie dite \"Bait and Hook\" (appât et hameçon) des consommables.", "Son modèle économique est financé exclusivement par le Crowdfunding communautaire (dons)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-76", chapter: 3, difficulte: "difficile", question: "L'hébergement du Progiciel (PGI) et des données critiques de l'entreprise sur des serveurs distants gérés par un prestataire comme Amazon (AWS) ou Microsoft (Azure) s'appelle :", choix: ["L'architecture réseau Peer-to-Peer (P2P).", "Le Cloud Computing (Informatique en nuage), qui apporte de l'agilité et transforme un lourd investissement initial (CAPEX) en abonnement variable (OPEX), tout en posant des questions de souveraineté des données.", "Le \"Shadow IT\" sécurisé (informatique de l'ombre autorisée).", "Le Crowdsourcing de logiciels libres (logiciels de la multitude)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-77", chapter: 3, difficulte: "difficile", question: "La \"désintermédiation\" accélérée par le numérique consiste pour un fabricant (par exemple Nike) à :", choix: ["Vendre directement ses baskets au consommateur final via son propre site e-commerce, en contournant et supprimant les magasins distributeurs classiques (ex: Intersport) pour capter 100% de la marge commerciale.", "Ajouter de nouveaux courtiers, intermédiaires et grossistes pour atteindre massivement les marchés internationaux.", "Remplacer sa monnaie de paiement traditionnelle par des cryptomonnaies décentralisées.", "Sous-traiter l'intégralité de sa production industrielle dans des pays émergents d'Asie."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-78", chapter: 3, difficulte: "difficile", question: "L'approche marketing et logistique dite \"Omnicanale\" exige pour réussir :", choix: ["De cloisonner hermétiquement et de gérer séparément le magasin physique et le site web (stratégie en silos).", "Une interopérabilité parfaite et en temps réel des systèmes d'information (stocks, CRM, caisses) pour offrir au consommateur un parcours d'achat \"sans couture\" et fluide entre le digital et le physique (ex: Click & Collect, retour en magasin d'un achat web).", "La suppression pure et simple de l'ensemble des vendeurs dans les boutiques physiques.", "L'abandon définitif de la tarification dynamique de type Yield Management."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-79", chapter: 3, difficulte: "difficile", question: "En matière de protection des données (RGPD européen), le principe de \"minimisation des données\" impose à l'entreprise de :", choix: ["Réduire la capacité de stockage de ses disques durs pour améliorer son bilan carbone et sa performance environnementale.", "Ne collecter, traiter et conserver que les données personnelles qui sont strictement adéquates, pertinentes et limitées à ce qui est nécessaire au vu des finalités annoncées (ex: ne pas exiger la date de naissance pour vendre une paire de ciseaux).", "Supprimer l'intégralité de sa base de données CRM (clients) au 31 décembre de chaque année comptable.", "N'utiliser dans son ciblage publicitaire que des données publiques libres de droits disponibles en Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-80", chapter: 3, difficulte: "difficile", question: "Une violente cyberattaque de type Ransomware (logiciel rançonneur) détruit les disques durs contenant les fichiers comptables d'une PME.", choix: ["Le pilier de la \"Transparence algorithmique\" de la cybersécurité est violé.", "Le pilier de la \"Disponibilité et l'intégrité de l'information\" est violé, l'entreprise se retrouvant paralysée car ses données critiques sont inaccessibles et/ou modifiées.", "Le pilier de la \"Rentabilité financière\" de l'audit comptable est détruit.", "Le pilier de la \"Traçabilité des emails\" du réseau intranet est corrompu."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-81", chapter: 3, difficulte: "difficile", question: "Le fait qu'une application tierce comme Google Maps puisse afficher les horaires des trains SNCF en temps réel nécessite une connexion logicielle spécifique entre les serveurs, appelée :", choix: ["Clé primaire du modèle relationnel (SQL).", "API (Interface de Programmation d'Application), une porte d'accès sécurisée permettant l'interopérabilité et l'échange de données entre les deux systèmes d'information distincts.", "Blockchain de transport décentralisée.", "Cloud hybride fermé de type intranet."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-82", chapter: 3, difficulte: "difficile", question: "Dans une base de données relationnelle (modèle SQL) gérant les clients, la \"clé primaire\" (ex: Numéro_Client_unique) a pour fonction de :", choix: ["Crypter la base de données pour empêcher le vol par rançongiciel.", "Identifier de manière absolument unique et non nulle chaque enregistrement (chaque ligne client) d'une table, évitant les doublons et garantissant l'intégrité référentielle des données.", "Bloquer les attaques de déni de service (DDoS) sur le serveur web.", "Partager automatiquement les données non confidentielles en Open Data avec l'État."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-83", chapter: 3, difficulte: "difficile", question: "\"Aéspace Valley\" regroupe autour de Toulouse le géant Airbus, une multitude de sous-traitants, des écoles d'ingénieurs aéronautiques et des laboratoires de recherche publics.", choix: ["L'enjeu de ce \"Cluster\" (pôle de compétitivité) est de s'isoler géographiquement de la féroce concurrence mondiale en créant un monopole.", "L'enjeu de ce \"Cluster\" est de bénéficier d'externalités positives de réseau géographique (transfert rapide de compétences, émulation technologique en R&D, vaste bassin d'emploi hyper-qualifié) qui rendent l'ensemble du territoire hyper-compétitif à l'international.", "L'enjeu est de pratiquer le mécénat environnemental, rendu obligatoire par les directives RSE de l'Union Européenne.", "L'enjeu est de faciliter l'imposition par l'État d'une centralisation du pouvoir décisionnel industriel."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-84", chapter: 3, difficulte: "difficile", question: "L'outil informatisé \"Workflow\" (Flux de travaux) accroît significativement l'efficience d'un processus administratif (ex: validation d'un contrat) en :", choix: ["Rendant l'information opaque et inaccessible pour le personnel d'exécution, au profit des seuls dirigeants.", "Automatisant le routage des documents numériques, en encadrant strictement l'enchaînement des validations obligatoires, et en assurant la traçabilité complète des actions effectuées par chaque acteur.", "Remplaçant intégralement le jugement du DRH ou du directeur financier par un algorithme prédictif autonome.", "Mettant instantanément les données contractuelles en Open Data mondial pour garantir la transparence des affaires."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-85", chapter: 3, difficulte: "difficile", question: "Une PME industrielle choisit de confier la gestion intégrale de ses fiches de paie et de ses contrats de travail à un prestataire RH externe spécialisé (cabinet comptable).", choix: ["C'est de l'intégration verticale vers l'amont de la chaîne de valeur.", "C'est de l'externalisation (BPO - Business Process Outsourcing), décision stratégique permettant à la PME de variabiliser ses coûts RH et de se recentrer sur son cœur de métier (l'industrie), au prix d'une certaine dépendance envers le prestataire.", "C'est de la flexibilité interne qualitative, impliquant une restructuration des compétences des propres salariés de l'usine.", "C'est du Crowdsourcing administratif, reposant sur l'intelligence de la communauté web."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-86", chapter: 3, difficulte: "difficile", question: "Le \"Social Selling\" (vente sociale) pratiqué par les commerciaux sur le marché B2B (ventes entre entreprises) consiste à :", choix: ["Vendre des espaces publicitaires et des bannières web aux syndicats et comités d'entreprise.", "Remplacer l'appel téléphonique à froid (Cold Calling) par une utilisation stratégique des réseaux sociaux professionnels (ex: LinkedIn) pour identifier les prospects, démontrer son expertise, interagir et créer une relation de confiance avant de proposer une offre commerciale.", "Externaliser la force de vente terrain en faisant appel à des plateformes de freelances indépendants.", "Vendre les stocks de produits invendus de l'entreprise sur des groupes Facebook ou Marketplace à prix coûtant (déstockage)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-87", chapter: 3, difficulte: "difficile", question: "L'éthique dans les affaires (Compliance) s'impose de plus en plus aux grandes multinationales françaises via la loi sur le \"devoir de vigilance\", qui les oblige légalement à :", choix: ["Espionner par webcam les employés travaillant à domicile en télétravail pour garantir la confidentialité du SI.", "Établir un plan pour prévenir et traiter les risques graves d'atteinte aux droits humains fondamentaux (travail forcé) et à l'environnement, non seulement dans leurs propres usines, mais sur l'ensemble de leur chaîne de valeur mondiale (y compris chez leurs sous-traitants très lointains).", "Distribuer obligatoirement 50% de leurs bénéfices nets annuels (après impôts) à des ONG dans les pays émergents (Mécénat contraint).", "N'utiliser que des intelligences artificielles \"transparentes\" pour le recrutement de leurs cadres dirigeants."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-88", chapter: 3, difficulte: "difficile", question: "\"L'innovation de rupture\", telle que conceptualisée par l'économiste J. Schumpeter (ex: Netflix tuant les vidéoclubs Blockbuster, ou le smartphone remplaçant l'appareil photo numérique), s'accompagne toujours d'un phénomène brutal de :", choix: ["Coopétition asymétrique entre les start-ups et les acteurs historiques.", "\"Destruction créatrice\" : la nouvelle technologie ou le nouvel usage remplace l'ancien modèle dominant et provoque souvent la chute brutale des entreprises historiques qui n'ont pas su ou voulu pivoter, tout en créant de nouveaux marchés et de la croissance économique.", "Standardisation des qualifications et des procédés de travail à l'échelle du secteur industriel mondial.", "Stabilisation du seuil de rentabilité unitaire des produits concernés."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-89", chapter: 3, difficulte: "difficile", question: "Le financement d'un projet technologique par l'émission de \"Tokens\" (jetons numériques en cryptomonnaie) vendus sur internet à des investisseurs du monde entier s'appelle :", choix: ["Un emprunt bancaire obligataire indexé sur le taux d'intérêt de la Banque Centrale.", "Une ICO (Initial Coin Offering) reposant sur la technologie Blockchain, une forme totalement désintermédiée et non régulée de levée de fonds contournant les banques traditionnelles.", "Une augmentation de capital social classique soumise à l'Autorité des Marchés Financiers (AMF).", "Un crédit-bail adossé à des actifs logiciels immatériels."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-90", chapter: 3, difficulte: "difficile", question: "Une entreprise qui développe une nouvelle application mobile de manière \"Agile\" (ex: Méthode Scrum) se caractérise par le fait qu'elle :", choix: ["Fige un lourd cahier des charges extrêmement détaillé pendant 3 ans sans aucune modification avant de livrer le produit final parfait (méthode traditionnelle du Cycle en V).", "Procède par cycles de développement itératifs très courts (\"sprints\"), livre rapidement des versions intermédiaires (MVP - Produit Minimum Viable) et s'adapte en continu aux retours et aux tests des utilisateurs pour faire face à l'incertitude du marché.", "Refuse toute communication interne et travaille en silos hermétiques pour garantir le secret industriel de son code source.", "Utilise obligatoirement la supervision directe autocratique pour forcer les développeurs à tenir les délais impartis."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-91", chapter: 3, difficulte: "difficile", question: "Dans le domaine du Big Data, la création d'un \"Data Lake\" (Lac de données) permet stratégiquement à l'entreprise de :", choix: ["Structurer les données comptables et financières de manière très stricte dans des tables relationnelles (SQL) figées.", "Stocker massivement et à bas coût des données brutes, hétérogènes et non structurées (textes, vidéos, logs informatiques, signaux de capteurs IoT) en vue d'une exploration et d'une analyse prédictive ultérieure par des data scientists (Data Mining).", "Détruire automatiquement et irrémédiablement les données personnelles des clients après 30 jours pour satisfaire aux exigences drastiques du RGPD.", "Rafraîchir les serveurs de calcul avec de l'eau recyclée (Greenwashing technologique)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-92", chapter: 3, difficulte: "difficile", question: "Un \"biais algorithmique\" (ou biais d'apprentissage) décelé dans un logiciel d'Intelligence Artificielle utilisé pour trier les centaines de milliers de CV reçus par l'entreprise signifie que l'IA :", choix: ["Fait preuve d'une objectivité mathématique et statistique infaillible, dénuée de toute subjectivité.", "Reproduit et amplifie de manière aveugle (\"boîte noire\") des discriminations humaines passées (ex: sexisme, racisme) qui étaient présentes, souvent implicitement, dans les données historiques sur lesquelles l'algorithme a été entraîné (Machine Learning).", "Est victime d'une attaque externe par des hackers visant à paralyser le serveur via des requêtes multiples (DDoS).", "Refuse de lire les CV enregistrés au format PDF ou Word, exigeant un format Open Data."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-93", chapter: 3, difficulte: "difficile", question: "La campagne de communication digitale en ligne (\"Paid Media\") d'une entreprise consiste pour le service marketing à :", choix: ["Payer de l'espace publicitaire sur des plateformes (Meta, Google Ads) pour diffuser des annonces hyper-ciblées garantissant une visibilité et une acquisition de trafic immédiates.", "Espérer passivement qu'une vidéo postée par un influenceur \"fan\" devienne virale gratuitement sur les réseaux (Earned Media / Bouche-à-oreille).", "Mettre à jour et animer son propre site internet vitrine et sa page Facebook officielle (Owned Media).", "Publier son bilan comptable et ses objectifs de RSE en Open Data pour rassurer les parties prenantes."] as [string, string, string, string], bonIndex: 0 },
  { id: "sdgn-t-ds-94", chapter: 3, difficulte: "difficile", question: "L'utilisation persistante du \"Shadow IT\" (outils informatiques comme WhatsApp ou Google Drive non validés par la DSI) par les salariés pour aller plus vite dans leur travail quotidien illustre souvent en management le dangereux décalage entre :", choix: ["La rentabilité boursière exigée par les actionnaires et le BFR imposé par les fournisseurs.", "La lourdeur, la complexité ou la rigidité du Système d'Information officiel imposé par le siège, et le besoin irrépressible d'agilité, de fluidité et de rapidité d'exécution des collaborateurs sur le terrain opérationnel.", "L'architecture du Cloud privé hébergé en interne et celle du Cloud public hébergé par Amazon.", "Les engagements solennels de RSE annoncés par le dirigeant et les pratiques réelles de greenwashing."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-95", chapter: 3, difficulte: "difficile", question: "Une marque de cosmétique de luxe finance la recherche fondamentale contre les maladies orphelines dans un institut de santé public de manière très discrète, sans publicité. C'est du :", choix: ["Sponsoring (Parrainage) commercial, visant un retour sur investissement immédiat par la vente.", "Mécénat, c'est-à-dire un soutien financier (ou en nature) d'intérêt général apporté sans attente de contrepartie publicitaire directe ou de ROI (retour sur investissement) à court terme pour l'entreprise donatrice.", "Crowdfunding en Equity (financement participatif en capital) pour le compte de l'institut.", "Social Washing agressif, destiné à masquer un bilan carbone catastrophique."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-96", chapter: 3, difficulte: "difficile", question: "L'utilisation réussie par une entreprise de la stratégie de ciblage ultra-personnalisé \"One-to-One\" requiert technologiquement de sa part :", choix: ["De produire en masse des biens hyper-standardisés selon le modèle historique du Fordisme pour écraser les coûts de revient.", "D'exploiter algorithmiquement une base de données client (CRM) d'une grande richesse, qualifiée par les historiques d'achats et la navigation web, pour proposer des offres hyper-personnalisées (Big Data).", "De supprimer son système d'information marketing centralisé pour favoriser l'ajustement mutuel informel des vendeurs.", "De communiquer exclusivement par le biais de campagnes d'affichage urbain 4x3m \"Mass Market\"."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-97", chapter: 3, difficulte: "difficile", question: "Une organisation \"orientée processus\" (vision transversale) cherche à casser l'organisation traditionnelle en \"silos\" (fonctions verticales isolées qui ne se parlent pas). Elle utilisera préférentiellement comme architecture du système d'information :", choix: ["Une multitude d'applications métiers (logiciels de niche) totalement indépendantes et techniquement incompatibles (sans interopérabilité).", "Un Progiciel de Gestion Intégré (PGI/ERP) unique adossé à une base de données partagée, et des outils de Workflow interconnectant informatiquement les différents services (ventes, compta, stock) de bout en bout.", "Un réseau pair-à-pair (P2P) non sécurisé, installé en \"Shadow IT\" par les salariés eux-mêmes.", "Le rejet total de l'automatisation au profit exclusif de la supervision directe de la direction générale."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-98", chapter: 3, difficulte: "difficile", question: "L'essor massif, foudroyant et pérenne du commerce d'occasion en ligne (plateformes de type Vinted, LeBonCoin, BackMarket) traduit en marketing une profonde mutation sociétale vers :", choix: ["La consommation hyper-mondialisée de produits manufacturés jetables et polluants, encouragée par le triomphe de la Fast Fashion.", "L'économie circulaire, la rationalité économique (pouvoir d'achat face à l'inflation) et une montée en puissance de l'anti-consumérisme écologique (désir de prolonger la vie du produit).", "La demande exclusive par le client roi de produits manufacturés ultra-personnalisés et neufs à prix d'écrémage.", "La disparition programmée de la monnaie fiduciaire scripturale au profit du troc physique direct de main à main."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-99", chapter: 3, difficulte: "difficile", question: "En contrôle de gestion stratégique, le \"Tableau de Bord Prospectif\" (Balanced Scorecard de Norton & Kaplan) est jugé infiniment supérieur au seul bilan comptable pour piloter l'entreprise de demain car il :", choix: ["Ne se focalise strictement que sur les données financières passées et auditées de l'année N-1 (la rentabilité historique).", "Équilibre le pilotage de la performance globale sur quatre axes d'analyse interdépendants : Finance (rentabilité), Client (satisfaction/part de marché), Processus Internes (qualité/délais/productivité) et Apprentissage (RH/GPEC/Innovation).", "Est publié en Open Data sur le site du ministère de l'Économie pour valider le taux d'imposition sur les sociétés.", "Remplace techniquement le PGI de l'entreprise par des intelligences artificielles génératives (ChatGPT)."] as [string, string, string, string], bonIndex: 1 },
  { id: "sdgn-t-ds-100", chapter: 3, difficulte: "difficile", question: "(Le test ultime) La start-up technologique \"TechSuccess\" est en hypercroissance : ses ventes explosent sur le marché B2B. Son modèle d'affaires exige de payer les usines sous-traitantes asiatiques comptant à la commande, alors que ses gros clients (grandes surfaces) la paient à 60, voire 90 jours après livraison. La production tourne à plein régime. Le Directeur Général se réjouit du Chiffre d'Affaires record. Le Directeur Financier (DAF), lui, convoque une réunion de crise en panique absolue. Pourquoi le CFO a-t-il techniquement raison de s'alarmer ?", choix: ["Parce que l'hypercroissance des ventes augmente inévitablement les charges fixes structurelles du siège social, ce qui détruira l'effet de levier et la marge sur coûts spécifiques de l'année suivante, rendant les investissements obsolètes.", "Parce que la redoutée \"crise de croissance\" est mortelle : l'augmentation massive des ventes gonfle vertigineusement le Besoin en Fonds de Roulement (BFR) (explosion des créances clients en attente de paiement). Si le Fonds de Roulement (FRNG) n'est pas augmenté d'urgence (via une levée de fonds ou un emprunt long terme), la Trésorerie Nette s'effondrera instantanément dans le rouge, menant la start-up hyper-rentable (qui fait des bénéfices sur le papier)... directement à la cessation de paiements (faillite).", "Parce que les bénéfices exceptionnels générés par ce chiffre d'affaires devront être légalement reversés sous forme de participation obligatoire et d'intéressement aux salariés, ce qui entraînera un conflit de répartition irréversible de la valeur ajoutée avec les actionnaires.", "Parce que l'effet de levier financier deviendra mathématiquement négatif (effet de massue) si le chiffre d'affaires, exprimé en brut, dépasse d'un coup la valeur comptable des capitaux propres inscrits au passif du bilan."] as [string, string, string, string], bonIndex: 1 },
];
